import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv, texture, positionLocal, vec3, vec4, float, mix, uniform, mul, add,
  smoothstep, dot, luminance, max as tslMax
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight, Color } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {};
  const bg = colors.background ?? '#0b0b10';
  const accent = colors.accent ?? '#ff2a38';
  const paper = colors.paper ?? '#e8ecf2';

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl ?? '/prism-mock/home/nodes/parallax-stack.png';
  const depthUrl = config.depthMapUrl ?? config.intent?.visualSpec?.depthMapUrl ?? '/prism-mock/home/nodes/parallax-stack.depth.png';

  const group = new Group();
  const timelines = [];
  const primitiveHandles = [];
  const disposables = [];

  // ---- Backdrop stage plane (vertical gradient) ----
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const cTop = new Color(bg).offsetHSL(0, 0, 0.02);
  const cBottom = new Color(bg);
  backdropMat.colorNode = mix(
    vec3(cBottom.r, cBottom.g, cBottom.b),
    vec3(cTop.r, cTop.g, cTop.b),
    uv().y
  );
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---- Hero photo plate (displacement + filmic grade) ----
  const plateGeo = new PlaneGeometry(4.0, 2.5, 64, 64);
  const plateMat = new MeshStandardNodeMaterial();
  plateMat.roughness = 0.6;
  plateMat.metalness = 0.1;
  plateMat.transparent = true;

  const opacityU = uniform(0.0);
  const dispAmp = uniform(0.18);

  // Placeholder color until textures load
  plateMat.colorNode = vec3(0.05, 0.05, 0.07);
  plateMat.opacityNode = opacityU;

  const plate = new Mesh(plateGeo, plateMat);
  plate.position.set(0, 0.1, 0);
  group.add(plate);
  disposables.push(plateGeo, plateMat);

  // Load textures and wire displacement + filmic grade
  Promise.all([
    ctx.textureLoader.loadTexture(imageUrl),
    ctx.textureLoader.loadTexture(depthUrl)
  ]).then(([photoTex, depthTex]) => {
    const photo = texture(photoTex, uv());
    const depth = texture(depthTex, uv());

    // filmic grade: desaturate -8%, lift blacks, shoulder highlights, keep red
    const col = photo.rgb;
    const lum = luminance(col);
    const desat = mix(col, vec3(lum), float(0.08));
    // preserve red channel purity
    const graded = vec3(col.r, desat.g, desat.b);
    // lift blacks toward #0d0d12, shoulder highlights toward paper
    const black = vec3(0.051, 0.051, 0.071);
    const white = new Color(paper);
    const lifted = mix(black, graded, smoothstep(float(0.0), float(0.9), tslMax(graded.r, tslMax(graded.g, graded.b))));
    // midtone contrast +12%
    const contrasted = add(mul(add(lifted, float(-0.5)), float(1.12)), float(0.5));

    plateMat.colorNode = contrasted;

    // vertex displacement from depth map
    const dispVal = texture(depthTex, uv()).r;
    plateMat.positionNode = add(
      positionLocal,
      vec3(0, 0, mul(add(dispVal, float(-0.5)), dispAmp))
    );

    plateMat.needsUpdate = true;
  });

  // ---- Bottom scrim gradient plane (seats caption) ----
  const scrimGeo = new PlaneGeometry(4.0, 1.3);
  const scrimMat = new MeshBasicNodeMaterial();
  scrimMat.transparent = true;
  const scrimC = new Color(bg);
  scrimMat.colorNode = vec3(scrimC.r, scrimC.g, scrimC.b);
  // opaque at bottom (y=0), transparent at top (y=1)
  scrimMat.opacityNode = smoothstep(float(1.0), float(0.15), uv().y).mul(0.92);
  const scrim = new Mesh(scrimGeo, scrimMat);
  scrim.position.set(0, -0.6, 0.05);
  group.add(scrim);
  disposables.push(scrimGeo, scrimMat);

  // ---- Caption block (bottom-left) ----
  const captionGroup = new Group();
  const leftX = -1.75; // 0.5-unit padding from plate left edge (-2.0)
  let cursorY = -0.55;

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = {};
  for (const it of items) byRole[it.role] = it.text;

  const kicker = ctx.fontAtlas.createText(byRole.kicker ?? 'NOVA ATELIER / GENEVA', {
    fontSize: 34, color: paper, align: 'left', letterSpacingPx: 4
  });
  kicker.position.set(leftX, cursorY + 0.42, 0.1);
  captionGroup.add(kicker);

  const headline = ctx.fontAtlas.createText(byRole.headline ?? 'Time, Machined.', {
    fontSize: 96, color: paper, align: 'left'
  });
  headline.position.set(leftX, cursorY + 0.12, 0.1);
  captionGroup.add(headline);

  // accent hairline bar between headline and body
  const barGeo = new PlaneGeometry(0.75, 0.02);
  const barMat = new MeshStandardNodeMaterial();
  const accentC = new Color(accent);
  barMat.colorNode = vec3(accentC.r, accentC.g, accentC.b);
  barMat.emissiveNode = mul(vec3(accentC.r, accentC.g, accentC.b), float(1.8));
  const bar = new Mesh(barGeo, barMat);
  bar.position.set(leftX + 0.375, cursorY - 0.16, 0.1);
  captionGroup.add(bar);
  disposables.push(barGeo, barMat);

  const body = ctx.fontAtlas.createText(byRole.body ?? 'Every case begins as a single billet of 904L steel.', {
    fontSize: 42, color: paper, align: 'left', maxWidthPx: 900
  });
  body.position.set(leftX, cursorY - 0.34, 0.1);
  captionGroup.add(body);

  const caption = ctx.fontAtlas.createText(byRole.caption ?? 'CALIBRE NA-01 / 72 HOUR RESERVE', {
    fontSize: 30, color: '#9aa0aa', align: 'left', letterSpacingPx: 3
  });
  caption.position.set(leftX, cursorY - 0.58, 0.1);
  captionGroup.add(caption);

  group.add(captionGroup);

  // ---- Node-local lighting ----
  const ambient = new AmbientLight(0xffffff, 0.35);
  group.add(ambient);

  const rim = new DirectionalLight(new Color(accent), 0.9);
  rim.position.set(-3, 1.5, 2);
  group.add(rim);

  const key = new DirectionalLight(0xffffff, 1.0);
  key.position.set(2.5, 2.5, 3);
  group.add(key);

  // ---- Motion: plate fade-in, caption rise-in ----
  const tl = gsap.timeline();
  tl.to(opacityU, { value: 1.0, duration: 0.5, ease: 'power2.out' });

  captionGroup.position.y = 0.4;
  captionGroup.visible = true;
  tl.fromTo(captionGroup.position, { y: 0.4 }, {
    y: 0.0, duration: 0.7, ease: 'power3.out'
  }, 0.12);
  timelines.push(tl);

  // ---- Apply cinematic primitives ----
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives?.[p.name];
    if (fn) {
      const handle = fn(plate, p.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- Cleanup ----
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primitiveHandles.forEach((h) => h?.cleanup?.());
    disposables.forEach((d) => d?.dispose?.());
  };

  return group;
}
